const state={screen:"home",questions:[],enterprises:[],answers:[],preview:null,enterprise:null,step:0,scenarioAnswers:[],feedback:""};const labels={energy:"Энергетика",manufacturing:"Производство",ecology:"Экология",science:"Лаборатории",engineering:"Инженерия",logistics:"Логистика",digital:"Цифровые задачи"};async function api(path,body){const r=await fetch(`/api${path}`,body?{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)}:{});if(!r.ok)throw new Error(path);return r.json()}function $(s){return document.querySelector(s)}function shell(content){$("#app").innerHTML=`<header class="top"><div class="brand"><span class="mark">П</span><span>ПрофМаршрут</span></div><nav class="nav">${[["home","Старт"],["test","Тест"],["result","Результат"],["admin","Админка"]].map(([id,t])=>`<button class="${state.screen===id?"active":""}" data-nav="${id}">${t}</button>`).join("")}</nav></header>${content}<footer class="footer">MVP платформы онлайн-профориентации: входной тест → предприятия → игровой сценарий → итог.</footer>`;document.querySelectorAll("[data-nav]").forEach(b=>b.onclick=()=>go(b.dataset.nav))}function go(s){if(s==="result"&&state.answers.length<state.questions.length)s="test";state.screen=s;render();scrollTo(0,0)}function status(){const items=[["Тест",state.answers.length===state.questions.length],["Предварительный профиль",state.answers.length===state.questions.length],["Предприятие",!!state.enterprise],["Сценарий",state.scenarioAnswers.length>0],["Итог",state.screen==="final"]];return`<aside class="panel side"><h3>Состояние маршрута</h3><div class="status">${items.map(([t,d],i)=>`<div class="${d?"done":""}"><span class="dot">${d?"✓":i+1}</span><span>${t}</span></div>`).join("")}</div></aside>`}function home(){shell(`<section class="hero"><div class="hero-content"><div class="eyebrow">обязательный входной тест</div><h1>Профориентация через реальные предприятия</h1><p class="lead">Пользователь проходит короткий тест, получает профиль интересов, выбирает рекомендованную компанию и пробует профессию в игровом сценарии.</p><div class="actions"><button class="btn" id="start">▶ Начать тест</button><button class="btn secondary" onclick="document.querySelector('#flow').scrollIntoView()">⌖ Посмотреть путь</button></div></div><div class="strip">${[["10","вопросов в MVP-тесте"],["3–5","рекомендованных предприятий"],["2","уровня результата"],["B2B","карточки и сценарии компаний"]].map(x=>`<div class="metric"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join("")}</div></section><main class="main" id="flow"><section class="wrap"><h2>Пользовательский маршрут</h2><p class="lead">Предприятие открывается после диагностики, а финальный результат складывается из общего теста и сценария компании.</p><div class="panel cards">${["Старт и тест","Профиль интересов","Подбор предприятий"].map((t,i)=>`<div class="card"><h3>${i+1}. ${t}</h3><p>Шаг платформы по ТЗ.</p></div>`).join("")}</div></section></main>`);$("#start").onclick=()=>{state.answers=[];state.step=0;go("test")}}function test(){const q=state.questions[state.step];if(!q)return shell(`<main class="main">Тест не загружен</main>`);shell(`<main class="main"><section class="wrap grid route">${status()}<div class="panel pad"><div class="progress"><span style="width:${state.step/state.questions.length*100}%"></span></div><div class="qhead"><span>Вопрос ${state.step+1} из ${state.questions.length}</span><span>${q.hint||""}</span></div><h2>${q.text}</h2><div class="options">${q.answers.map(a=>`<button class="option ${state.answers[state.step]?.id===a.id?"selected":""}" data-a="${a.id}"><span class="radio"></span><span>${a.text}</span></button>`).join("")}</div><div class="actions"><button class="btn ghost" id="prev" ${state.step===0?"disabled":""}>← Назад</button><button class="btn" id="next" ${!state.answers[state.step]?"disabled":""}>${state.step===state.questions.length-1?"Показать результат":"Дальше →"}</button></div></div></section></main>`);document.querySelectorAll("[data-a]").forEach(b=>b.onclick=()=>{state.answers[state.step]=q.answers.find(a=>a.id==b.dataset.a);test()});$("#prev").onclick=()=>{state.step--;test()};$("#next").onclick=()=>state.step===state.questions.length-1?go("result"):(state.step++,test())}async function result(){state.preview=await api("/results/preview",{answerIds:state.answers.map(a=>a.id)}).catch(()=>state.preview);const ents=state.preview?.enterprises||state.enterprises;shell(`<main class="main"><section class="wrap grid route">${status()}<div><h2>${state.preview?.title||"Предварительный результат"}</h2><p class="lead">Результат теста влияет на подбор и порядок показа предприятий.</p><div class="panel pad"><h3>Ваши направления</h3><div class="taglist">${(state.preview?.topTags||[]).map(t=>`<span class="tag teal">${t.label}</span>`).join("")}</div></div><h2 style="margin-top:28px">Рекомендованные предприятия</h2><div class="cards">${ents.map(e=>`<article class="panel card"><div><div class="meta"><span>${e.sector} · ${e.city}</span><span class="score">${e.match||0}%</span></div><h3>${e.name}</h3><p>${e.description}</p><div class="taglist">${Object.keys(e.tags||{}).slice(0,4).map(t=>`<span class="tag">${labels[t]||t}</span>`).join("")}</div></div><button class="btn" data-e="${e.id}">Открыть карточку →</button></article>`).join("")}</div></div></section></main>`);document.querySelectorAll("[data-e]").forEach(b=>b.onclick=()=>{state.enterprise=ents.find(e=>e.id==b.dataset.e);state.step=0;state.scenarioAnswers=[];state.feedback="";go("enterprise")})}function enterprise(){const e=state.enterprise;shell(`<main class="main"><section class="wrap grid route">${status()}<div class="panel pad"><div class="grid cols"><div><div class="meta"><span>${e.sector} · ${e.city}</span><span>карточка предприятия</span></div><h2>${e.name}</h2><p class="lead">${e.description}</p><ul class="list">${[e.reason,"Сценарий содержит вопросы, задания, ответы, баллы и обратную связь.","Итог будет объединен с результатом входного теста."].map(t=>`<li><span class="check">✓</span><span>${t}</span></li>`).join("")}</ul><div class="actions"><button class="btn" id="startScenario">▶ Запустить сценарий</button><button class="btn ghost" onclick="go('result')">← К подборке</button></div></div><div><h3>Профессии предприятия</h3>${e.professions.map(p=>`<div class="profession"><strong>${p.title}</strong><span>${p.description}</span></div>`).join("")}</div></div></div></section></main>`);$("#startScenario").onclick=()=>go("scenario")}function scenario(){const e=state.enterprise,t=e.scenario.tasks[state.step],sel=state.scenarioAnswers[state.step],sum=state.scenarioAnswers.reduce((s,a)=>s+(a?.points||0),0);shell(`<main class="main"><section class="wrap grid route">${status()}<div class="grid scenario"><div class="panel pad"><div class="progress"><span style="width:${state.step/e.scenario.tasks.length*100}%"></span></div><div class="qhead"><span>${e.name}: этап ${state.step+1} из ${e.scenario.tasks.length}</span><span>${sel?`+${sel.points} баллов`:"ожидает решения"}</span></div><h2>${t.title}</h2><p class="lead">${t.prompt}</p><div class="visual"><div class="nodes">${t.visual.map((v,i)=>`<div class="node ${i%3===0?"hot":""}">${v}</div>`).join("")}</div></div><div class="options">${t.answers.map(a=>`<button class="option ${sel?.id===a.id?"selected":""}" data-sa="${a.id}"><span class="radio"></span><span>${a.text}</span></button>`).join("")}</div><div class="actions"><button class="btn ghost" id="sprev" ${state.step===0?"disabled":""}>← Назад</button><button class="btn" id="snext" ${!sel?"disabled":""}>${state.step===e.scenario.tasks.length-1?"Финальный итог":"Следующий этап →"}</button></div></div><aside class="panel pad"><h3>Баллы сценария</h3><div class="scorebig">${sum}</div><div class="feedback">${state.feedback||"После выбора ответа здесь появится обратная связь."}</div></aside></div></section></main>`);document.querySelectorAll("[data-sa]").forEach(b=>b.onclick=()=>{state.scenarioAnswers[state.step]=t.answers.find(a=>a.id==b.dataset.sa);state.feedback=t.feedback;scenario()});$("#sprev").onclick=()=>{state.step--;state.feedback="";scenario()};$("#snext").onclick=()=>state.step===e.scenario.tasks.length-1?go("final"):(state.step++,state.feedback="",scenario())}async function final(){const e=state.enterprise,sum=state.scenarioAnswers.reduce((s,a)=>s+(a?.points||0),0);await api("/results/final",{answerIds:state.answers.map(a=>a.id),enterpriseId:e.id,scenarioAnswers:state.scenarioAnswers}).catch(()=>{});shell(`<main class="main"><section class="wrap grid route">${status()}<div class="panel pad"><div class="meta"><span>финальный результат</span><span>${sum} баллов</span></div><h2>${state.preview?.title||"Профиль"} + сценарий «${e.name}»</h2><p class="lead">Общий профиль входного теста объединен с прохождением сценария предприятия.</p><div class="grid cols"><div class="panel pad"><h3>Рекомендация по профессии</h3><p><strong>${e.professions[0].title}</strong><br>${e.professions[0].description}</p></div><div class="panel pad"><h3>Почему это подходит</h3><p>${e.reason}</p></div></div><div class="actions"><button class="btn" id="mail">✉ Отправить на email</button><button class="btn secondary" onclick="go('result')">⌖ Другие предприятия</button><button class="btn ghost" onclick="state.answers=[];state.enterprise=null;state.scenarioAnswers=[];go('home')">↺ Пройти заново</button></div><p id="note"></p></div></section></main>`);$("#mail").onclick=async()=>{$("#note").textContent=(await api("/email-results",{email:"demo@example.com"})).message}}function admin(){shell(`<main class="main"><section class="wrap"><h2>Административная часть</h2><p class="lead">Управление разделено на общеплатформенный входной тест и самостоятельный контент предприятий.</p><div class="grid admin">${["Общеплатформенный тест","Карточки предприятий","Сущности данных","Технический стек"].map(t=>`<article class="panel pad"><h3>${t}</h3><ul><li>Вопросы, баллы, теги и веса</li><li>Профессии, сценарии и результаты</li><li>SQLite без ORM, Express API</li></ul></article>`).join("")}</div></section></main>`)}function render(){if(state.screen==="home")home();if(state.screen==="test")test();if(state.screen==="result")result();if(state.screen==="enterprise")enterprise();if(state.screen==="scenario")scenario();if(state.screen==="final")final();if(state.screen==="admin")admin()}async function init(){const data=await api("/bootstrap").catch(()=>({test:{questions:[]},enterprises:[]}));state.questions=data.test.questions;state.enterprises=data.enterprises;render()}init();
